arguments.command:
python -c "
import parse
p = parse.Parser('''
            letters: {:w}
            non-letters: {:W}
            whitespace: \"{s}\"
            non-whitespace: \t{:S}\n
            digits: {:d}
            non-digits: {:D}
            numbers with thousands: {:n}
            fixed-point: {:f}
            floating-point: {:e}
            general numbers: {:g} {:g}
            binary: {:b}
            octal: {:o}
            hex: {:x}
        ''')
print('Expression:', p._expression[:500])
" 2>&1
